<template>
  <div class="page">
    <div class="goods-manage__table-wrap">
      <div class="panel">
        <div class="panel__header">
          <div class="panel__title">
            <h3>商品管理</h3>
          </div>
          <div class="panel__actions">
            <el-button type="primary" size="small" @click="openAddDialog">新增商品</el-button>
          </div>
        </div>
        <div class="panel__table-wrap">
          <el-table ref="tableRef" :data="pagedData" style="width: 100%" :header-cell-style="{ textAlign: 'left' }" :cell-style="{ textAlign: 'left' }">
            <el-table-column prop="name" label="商品名称" min-width="180" />
            <el-table-column label="分类" min-width="110">
              <template #default="scope">{{ scope.row.categoryName || '-' }}</template>
            </el-table-column>
            <el-table-column label="价格" min-width="110">
              <template #default="scope">{{ formatPrice(scope.row.price) }}</template>
            </el-table-column>
            <el-table-column prop="sales" label="销量" min-width="90" />
            <el-table-column label="状态" min-width="90">
              <template #default="scope">
                <el-tag :type="scope.row.status === 1 ? 'success' : 'danger'" disable-transitions>
                  {{ scope.row.status === 1 ? '上架' : '下架' }}
                </el-tag>
              </template>
            </el-table-column>
            <el-table-column prop="createTime" label="上架时间" min-width="170" />
            <el-table-column label="操作" min-width="180">
              <template #default="scope">
                <el-button size="small" type="primary" link @click="openEditDialog(scope.row)">编辑</el-button>
                <el-button size="small" type="danger" link @click="handleDelete(scope.row)">删除</el-button>
              </template>
            </el-table-column>
          </el-table>
        </div>
      </div>
      <div class="goods-manage__pagination-wrap">
        <div class="totalnum">
          <h3>商品统计</h3>
          <p>当前共 {{ tableData.length }} 个商品</p>
        </div>
        <div class="example-pagination-block">
          <el-pagination
            layout="prev, pager, next"
            :total="tableData.length"
            :page-size="pageSize"
            :current-page="currentPage"
            @current-change="currentPage = $event"
          />
        </div>
      </div>

      <el-dialog v-model="dialogVisible" :title="dialogTitle" width="560px">
        <el-form ref="addFormRef" :model="addForm" :rules="addFormRules" label-width="80px">
          <el-form-item label="商品名称" prop="name">
            <el-input v-model="addForm.name" placeholder="请输入商品名称" />
          </el-form-item>
          <el-form-item label="分类" prop="category_id">
            <el-select v-model="addForm.category_id" placeholder="请选择分类" style="width: 100%">
              <el-option v-for="item in categories" :key="item.id" :label="item.name" :value="item.id" />
            </el-select>
          </el-form-item>
          <el-form-item label="价格" prop="price">
            <el-input-number v-model="addForm.price" :min="0" :precision="2" :step="0.5" style="width: 100%" />
          </el-form-item>
          <el-form-item label="原价" prop="original_price">
            <el-input-number v-model="addForm.original_price" :min="0" :precision="2" :step="0.5" style="width: 100%" />
          </el-form-item>
          <el-form-item label="商品描述" prop="description">
            <el-input v-model="addForm.description" type="textarea" :rows="2" placeholder="请输入商品描述" />
          </el-form-item>
          <el-form-item label="商品图片" prop="image">
            <el-input v-model="addForm.image" placeholder="请输入图片地址，如 https://example.com/img/1.png" />
          </el-form-item>
          <el-form-item label="商品标签" prop="tags">
            <el-select
              v-model="addForm.tags"
              multiple
              filterable
              allow-create
              default-first-option
              :reserve-keyword="false"
              placeholder="输入后回车添加标签"
              style="width: 100%"
            >
              <el-option v-for="tag in addForm.tags" :key="tag" :label="tag" :value="tag" />
            </el-select>
          </el-form-item>
          <el-form-item label="主要成分" prop="ingredients">
            <el-select
              v-model="addForm.ingredients"
              multiple
              filterable
              allow-create
              default-first-option
              :reserve-keyword="false"
              placeholder="输入后回车添加成分"
              style="width: 100%"
            >
              <el-option v-for="item in addForm.ingredients" :key="item" :label="item" :value="item" />
            </el-select>
          </el-form-item>
          <el-form-item label="商品详情" prop="details">
            <el-input v-model="addForm.details" type="textarea" :rows="3" placeholder="请输入商品详情" />
          </el-form-item>
          <el-form-item label="状态" prop="status">
            <el-select v-model="addForm.status" style="width: 100%">
              <el-option label="上架" :value="1" />
              <el-option label="下架" :value="0" />
            </el-select>
          </el-form-item>
        </el-form>
        <template #footer>
          <el-button @click="dialogVisible = false">取消</el-button>
          <el-button type="primary" @click="handleSubmit">确 定</el-button>
        </template>
      </el-dialog>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, reactive, onMounted, getCurrentInstance } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
const {proxy} = getCurrentInstance()

const currentPage = ref(1)
const pageSize = ref(6)


// 分类(categories 表)
const categories = ref([])
// 获取分类列表
const getCategoryList = () => {
  proxy.$request({
    url: '/api/categories',
    method: 'GET',
  }).then((res) => {
    categories.value = res.data || []
  })
}
// 新增/编辑商品(products 表)
const dialogVisible = ref(false)
const dialogMode = ref('add') // add | edit
const editIndex = ref(-1)
const dialogTitle = computed(() => (dialogMode.value === 'add' ? '新增商品' : '编辑商品'))
const addFormRef = ref()
const addForm = reactive({
  name: '',
  category_id: '',
  price: null,
  original_price: null,
  description: '',
  image: '',
  tags: [],
  ingredients: [],
  details: '',
  status: 1,
})
const addFormRules = {
  name: [{ required: true, message: '请输入商品名称', trigger: 'blur' }],
  category_id: [{ required: true, message: '请选择分类', trigger: 'change' }],
  price: [{ required: true, message: '请输入价格', trigger: 'blur' }],
}
// 新增商品
const openAddDialog = () => {
  dialogMode.value = 'add'
  addForm.name = ''
  addForm.category_id = ''
  addForm.price = null
  addForm.original_price = null
  addForm.description = ''
  addForm.image = ''
  addForm.tags = []
  addForm.ingredients = []
  addForm.details = ''
  addForm.status = 1
  dialogVisible.value = true
}
// 编辑商品
const openEditDialog = (row) => {
  dialogMode.value = 'edit'
  editIndex.value = tableData.value.indexOf(row)
  addForm.name = row.name
  addForm.category_id = row.categoryId
  addForm.price = row.price
  addForm.original_price = row.originalPrice
  addForm.description = row.description || ''
  addForm.image = row.image || ''
  addForm.tags = [...(row.tags || [])]
  addForm.ingredients = [...(row.ingredients || [])]
  addForm.details = row.details || ''
  addForm.status = row.status
  dialogVisible.value = true
}
// 提交表单
const handleSubmit = () => {
  addFormRef.value.validate((valid) => {
    if (!valid) return
    if (dialogMode.value === 'add') {
      // 构造要提交给后端的对象；tags/ingredients 后端是 String，需转成 JSON 字符串
      const submitItem = {
        categoryId: addForm.category_id,
        name: addForm.name,
        description: addForm.description,
        price: addForm.price,
        originalPrice: addForm.original_price,
        image: addForm.image || null,
        sales: 0,
        tags: JSON.stringify(addForm.tags),
        ingredients: JSON.stringify(addForm.ingredients),
        details: addForm.details,
        status: addForm.status,
      }
      //请求后端添加数据
      proxy.$request({
        url: '/api/products/add',
        method: 'POST',
        data: submitItem,
      }).then(() => {
        currentPage.value = 1
        ElMessage.success(`商品「${addForm.name}」已新增`)
      })
    } else {
      //
      const row = tableData.value[editIndex.value]
      const submitItem = {
        categoryId: addForm.category_id,
        name: addForm.name,
        description: addForm.description,
        price: addForm.price,
        originalPrice: addForm.original_price,
        image: addForm.image || null,
        tags: JSON.stringify(addForm.tags),
        ingredients: JSON.stringify(addForm.ingredients),
        details: addForm.details,
        status: addForm.status,
      }
      // 更新数据
      proxy.$request({
        url: `/api/products/${row.id}`, // id拼到url路径
        method: 'PUT', // 请求方法改成PUT
        data: submitItem,
      }).then(() => {
        // 刷新当前页数据
        fetchProducts()
      })
      ElMessage.success(`商品「${addForm.name}」已更新`)
    }
    dialogVisible.value = false
  })
}

// 格式化价格
const formatPrice = (price) => (price == null ? '-' : `¥${Number(price).toFixed(2)}`)

// 删除商品
const handleDelete = (row) => {
  ElMessageBox.confirm(`确定删除商品「${row.name}」吗？`, '提示', { type: 'warning' })
    .then(() => {
      proxy.$request({
        url: `/api/products/${row.id}`, // id拼到url路径
        method: 'DELETE',
      }).then(() => {
        ElMessage.success(`商品「${row.name}」已删除`)
        fetchProducts()
      })
    })
    .catch(() => {}) // 取消删除
}
// 分页数据
const pagedData = computed(() => {
  const start = (currentPage.value - 1) * pageSize.value
  return tableData.value.slice(start, start + pageSize.value)
})

// 商品数据(products 表结构)
const tableData = ref([])
// 从商品详情接口拉取商品列表
const fetchProducts = () => {
  proxy.$request({
    url: '/api/products/detail',
    method: 'GET',
  }).then((res) => {
    tableData.value = res.data || []
    // 转换 tags/ingredients 字符串为数组
    tableData.value.forEach((item) => {
      item.tags = JSON.parse(item.tags || '[]')
      item.ingredients = JSON.parse(item.ingredients || '[]')
    })
  })
}
//在组件挂载时获取商品列表和分类列表
onMounted(() => {
  getCategoryList() // 初始化获取分类列表
  fetchProducts() // 初始化获取商品列表
})
</script>

<style scoped>
.goods-manage__table-wrap {
  background-color: #ffffff;
  margin: 12px;
  border-radius: 8px;
  min-width: 0;
  overflow-x: auto;
}
